import{_ as o}from"./chunks/第一步-03.D7lAR9Hu.js";import{_ as t,o as d,c as a,a2 as c}from"./chunks/framework.CqGPl1zp.js";const r="/newx-doc/assets/%E7%AC%AC%E4%B8%80%E6%AD%A5-01.7nWpfnwh.png",l="/newx-doc/assets/%E7%AC%AC%E4%B8%80%E6%AD%A5-02.DaBn5bbA.png",p="/newx-doc/assets/%E7%AC%AC%E4%BA%8C%E6%AD%A5-01.BNA1yjjt.png",_="/newx-doc/assets/%E5%B7%A5%E4%BD%9C%E5%8F%B0.Be2AdSN0.png",A=JSON.parse('{"title":"功能开启","description":"","frontmatter":{},"headers":[],"relativePath":"oa/build.md","filePath":"oa/build.md","lastUpdated":null}'),i={name:"oa/build.md"};function s(n,e,u,m,h,b){return d(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="功能开启" tabindex="-1">功能开启 <a class="header-anchor" href="#功能开启" aria-label="Permalink to &quot;功能开启&quot;">​</a></h1><p>进度说明：</p><ul><li>管理后台，请使用 <a href="https://gitee.com/yudaocode/yudao-ui-admin-vue3" target="_blank" rel="noreferrer">https://gitee.com/yudaocode/yudao-ui-admin-vue3</a> 仓库的 <code>master</code> 分支</li><li>后端项目，请使用 <a href="https://gitee.com/zhijiantianya/ruoyi-vue-pro" target="_blank" rel="noreferrer">https://gitee.com/zhijiantianya/ruoyi-vue-pro</a> 仓库的 <code>master</code>（JDK8）、<code>master-jdk17</code>（JDK17/21）或 <code>master-jdk25</code>（JDK25）分支</li></ul><p>OA 系统，后端由 <code>yudao-module-oa</code> 模块实现，前端由 <code>yudao-ui-admin-vue3</code> 的 <code>oa</code> 目录实现。</p><p>考虑到编译速度，默认 <code>yudao-module-oa</code> 模块是关闭的，需要手动开启。步骤如下：</p><ul><li>第一步，开启 <code>yudao-module-oa</code> 模块</li><li>第二步，导入 OA 系统的 SQL 数据库脚本</li><li>第三步，重启后端项目，确认功能是否生效</li><li>第四步，初始化 OA 审批流程</li></ul><p>补充说明：</p><p>由于 OA 的用品领用、用印、会议室预定、用车、公文、出差报销、请假加班等申请使用到 BPM 的审批功能，所以你需要先看 <a href="./../bpm">《工作流》</a> 文档，将工作流开启！工作汇报的提交只改变汇报状态，不经过 BPM 审批。</p><h2 id="_1-第一步-开启模块" tabindex="-1">1. 第一步，开启模块 <a class="header-anchor" href="#_1-第一步-开启模块" aria-label="Permalink to &quot;1. 第一步，开启模块&quot;">​</a></h2><p>① 修改根目录的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/pom.xml" target="_blank" rel="noreferrer"><code>pom.xml</code></a> 文件，取消 <code>yudao-module-oa</code> 模块的注释。如下图所示：</p><p><img src="'+r+'" alt="取消  模块的注释"></p><p>② 修改 <code>yudao-server</code> 目录的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-server/pom.xml" target="_blank" rel="noreferrer"><code>pom.xml</code></a> 文件，引入 <code>yudao-module-oa</code> 模块。如下图所示：</p><p><img src="'+l+'" alt="引入  模块"></p><p>③ 点击 IDEA 右上角的【Reload All Maven Projects】，刷新 Maven 依赖。如下图所示：</p><p><img src="'+o+'" alt="刷新 Maven 依赖"></p><h2 id="_2-第二步-导入-sql" tabindex="-1">2. 第二步，导入 SQL <a class="header-anchor" href="#_2-第二步-导入-sql" aria-label="Permalink to &quot;2. 第二步，导入 SQL&quot;">​</a></h2><p>点击 <a href="https://lwb8832652.github.io/newx-doc/sql/oa.sql" target="_blank" rel="noreferrer">下载 SQL</a> 直接下载 SQL 文件，导入到数据库中。如下图所示：</p><p>友情提示：↑↑↑ oa.sql 是可以点击下载的！ ↑↑↑</p><p>重要说明：该 SQL 仅芋道星球成员可使用和商用，否则视为侵权（索赔 100 万，永久追溯）【下载即视为同意】。</p><p><img src="'+p+'" alt="导入数据库"></p><p>以 <code>oa_</code> 作为前缀的表，就是 OA 模块当前源码维护的表，一共 <strong>48</strong> 张，按业务模块分为：</p><table tabindex="0"><thead><tr><th>子前缀</th><th>模块</th><th>表数量</th></tr></thead><tbody><tr><td><code>oa_schedule*</code>、<code>oa_task*</code>、<code>oa_plan</code>、<code>oa_work_report</code></td><td>工作协作</td><td>7</td></tr><tr><td><code>oa_announcement*</code>、<code>oa_discussion*</code>、<code>oa_vote*</code>、<code>oa_contact*</code>、<code>oa_note*</code></td><td>信息协作</td><td>13</td></tr><tr><td><code>oa_mail_*</code></td><td>企业邮箱</td><td>4</td></tr><tr><td><code>oa_file_*</code></td><td>企业云盘</td><td>3</td></tr><tr><td><code>oa_supply_*</code>、<code>oa_seal*</code></td><td>办公用品与用印</td><td>5</td></tr><tr><td><code>oa_meeting_room*</code>、<code>oa_vehicle*</code></td><td>会议室与车辆</td><td>5</td></tr><tr><td><code>oa_official_doc_*</code></td><td>公文管理</td><td>3</td></tr><tr><td><code>oa_travel_*</code>、<code>oa_reimbursement</code></td><td>出差与报销</td><td>3</td></tr><tr><td><code>oa_attendance</code>、<code>oa_leave_apply</code>、<code>oa_overtime_apply</code>、<code>oa_regular_apply</code>、<code>oa_resign_apply</code></td><td>考勤与人事申请</td><td>5</td></tr></tbody></table><h2 id="_3-第三步-重启项目" tabindex="-1">3. 第三步，重启项目 <a class="header-anchor" href="#_3-第三步-重启项目" aria-label="Permalink to &quot;3. 第三步，重启项目&quot;">​</a></h2><p>重启后端项目，然后访问前端的 OA 菜单，确认功能是否生效。如下图所示：</p><p><img src="'+_+'" alt="确认功能是否生效"></p><p>如果菜单未显示，检查当前角色是否分配了「OA 办公协同」菜单及对应权限，重新登录后查看。</p><h2 id="_4-第四步-初始化审批流程" tabindex="-1">4. 第四步，初始化审批流程 <a class="header-anchor" href="#_4-第四步-初始化审批流程" aria-label="Permalink to &quot;4. 第四步，初始化审批流程&quot;">​</a></h2><p>OA 的申请表单由业务模块实现，审批节点、审批人及流程进度由 BPM 提供。</p><p>① 在 IDEA 中，打开 <code>yudao-module-oa/src/test/java/cn/iocoder/yudao/module/oa/service/OaBpmModelInitTest.java</code>。</p><p>② 确认本地后端已启动并开启 mock 登录，按实际环境配置类中的 <code>BASE_URL</code>（后端接口地址）、<code>TENANT_ID</code>（租户编号）、<code>USER_ID</code>（用户编号）和 <code>TOKEN</code>（mock 登录令牌）。</p><p>③ 在 IDEA 中执行对应业务的初始化测试方法。测试会读取流程文件，设置流程管理人为 <code>USER_ID</code>，导入并发布流程；已存在的模型不会覆盖，尚未发布时补充发布，已发布时不重复创建流程版本。</p><p>④ 进入 [工作流程 -&gt; 流程管理 -&gt; 流程模型] 菜单，检查流程管理人、发起权限、审批人和业务表单配置，确认流程已发布。<strong>仅导入模型但未发布时，业务申请不能正常提交。</strong></p><table tabindex="0"><thead><tr><th>业务</th><th>流程标识</th></tr></thead><tbody><tr><td>用品领用</td><td><code>oa_supply_apply</code></td></tr><tr><td>用印申请</td><td><code>oa_seal_apply</code></td></tr><tr><td>会议室预定</td><td><code>oa_meeting_room_booking</code></td></tr><tr><td>用车、还车</td><td><code>oa_vehicle_apply</code>、<code>oa_vehicle_return</code></td></tr><tr><td>公文发文、收文</td><td><code>oa_official_doc_send</code>、<code>oa_official_doc_receive</code></td></tr><tr><td>出差、差旅报销</td><td><code>oa_travel_apply</code>、<code>oa_travel_reimbursement</code></td></tr><tr><td>普通费用报销</td><td><code>oa_reimbursement</code></td></tr><tr><td>请假、加班</td><td><code>oa_leave_apply</code>、<code>oa_overtime_apply</code></td></tr><tr><td>转正、离职</td><td><code>oa_regular_apply</code>、<code>oa_resign_apply</code></td></tr></tbody></table><p>至此，我们就成功开启了 OA 的功能 🙂</p>',34)])])}const f=t(i,[["render",s]]);export{A as __pageData,f as default};
